// Basic variable injection
PromptTemplate template = new PromptTemplate(
    "Summarise this Java exception in plain English: {stackTrace}"
);
Prompt prompt = template.create(Map.of("stackTrace", stackTrace));
ChatResponse response = chatModel.call(prompt);
String summary = response.getResult().getOutput().getContent();

// System + user messages via ChatClient fluent API
ChatClient client = ChatClient.builder(chatModel)
    .defaultSystem("You are a senior Java architect. Be concise and precise.")
    .build();

String answer = client.prompt()
    .user(u -> u.text("Explain {topic} in two sentences").param("topic", "CompletableFuture"))
    .call()
    .content();

// ChatOptions to control temperature per call
ChatOptions options = ChatOptionsBuilder.builder()
    .withTemperature(0.2f)   // low temperature for deterministic output
    .withMaxTokens(200)
    .build();
